                ["وَكَـمْ قَصَمْنَا مِن قَرْيَةٍ كَانَتْ ظَـٰلِمَةً"],["إِذَا طَلَعَت تَّزَ ٰوَرُ عَن كَهْفِهِمْ ذَاتَ الْـيَمِينِ"],["وَإِذَا غَـرَبَت تَّـقْرِضُهُمْ ذَاتَ الشِّمَالِ"],["قَالَ قَدْ أُجِيبَت دَّعْوَتُـكُـمَا فَاسْتَقِيمَا"],["إِذْ أَ يَّدتُّكَ بِرُوحِ الْقُدُسِ تُـكَلِّـمُ النَّاسَ"],["وَاقْتُلُوهُمْ حَيْثُ وَجَدتُّـمُوهُمْ"],["رَبَّـنَا وَءَاتِنَا مَا وَعَدتَّـنَا عَلَىٰ رُسُلِكَ وَلَا تُخْزِنَا"],["الَّذِينَ عَـٰهَدتَّ مِنْهُمْ ثُمَّ يَنقُضُونَ عَهْدَهُمْ"]
